-- A sheet's settings. A user name's role on a sheet: CLERK (the default for a name with no row)
-- or STEWARD. Setting a name's role again replaces it.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(200) NOT NULL,
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL,
    PRIMARY KEY (sheet_id, user_name)
);
-- The sheet's clerk limit: a clerk can settle a claim only when its due is at or below it. Null
-- (or no row) is no limit.
CREATE TABLE sheet_setting (
    sheet_id    VARCHAR(200) NOT NULL PRIMARY KEY,
    clerk_limit DECIMAL(12,2)
);
-- The sheet's floor: a claim's live due is at least it. Null (or no row) is the default, 1.00.
ALTER TABLE sheet_setting ADD COLUMN floor DECIMAL(12,2);
-- The sheet's terms, in days: a claim is due by its date plus them. Null (or no row) is the default, 14.
ALTER TABLE sheet_setting ADD COLUMN terms INT;
-- The sheet's late percent, two decimals: an overdue claim's due gains it for every full 30 days
-- overdue. Null (or no row) is the default, 0.00.
ALTER TABLE sheet_setting ADD COLUMN late_pct DECIMAL(7, 2);
# The sheet's settings: its clerk limit and the roles given to user names.
respond:
  class: net.officefloor.hq.app.settings.RespondWithSettings
  govern: [ readonly-transaction ]
# Change the sheet's clerk limit, floor and/or terms. Validate first so a bad value is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.settings.ValidateSettings
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves (the floor moves dues).
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.settings.SaveSettings
  govern: [ transaction ]
  next: record
# Audit only once the change is saved: a refused change writes no line.
record:
  class: net.officefloor.hq.app.settings.RecordSettingChanged
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.settings.RespondWithSettings
  govern: [ transaction ]

